        message: `"${check.title}" has unresolved "NEEDS HUMAN INPUT" items. Resolve them with a concrete answer.`,
        source: 'validator'
      });
    }
    const bodyLines = body.split(/\r?\n/);
    for (const i of emptyFieldIndexes(bodyLines)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Unanswered field in "${check.title}": ${bodyLines[i].trim()}`,
        source: 'validator'
      });
    }
    if (check.expectsNumbers && !/\d/.test(answered)) {
      findings.push({
        checkId: check.id,
        severity: 'warn',
        message: `"${check.title}" has no numeric threshold. A check that cannot fail is not a check.`,
        source: 'validator'
      });
    }

    if (check.id === 'risk-tier') {
      tier = extractTier(body);
      if (!tier) {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier must be one of: prohibited, high, limited, minimal.',
          source: 'validator'
        });
      } else if (tier === 'prohibited') {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier is "prohibited" - this feature must not be built.',
          source: 'validator'
        });
      } else if (tier === 'high') {
        const empty = emptyFieldIndexes(bodyLines);
        const labelled = bodyLines.findIndex(
          (l, i) => /^\s*[-*]\s*\*\*\s*sign[- ]?off/i.test(l) && !empty.has(i)
        );
        const signoffIdx =
          labelled >= 0
            ? labelled
            : bodyLines.findIndex((l, i) => /sign[- ]?off/i.test(l) && !empty.has(i));
        let signoffValue = '';
        if (signoffIdx >= 0) {
          signoffValue = FIELD.test(bodyLines[signoffIdx])
            ? fieldText(bodyLines, signoffIdx)
            : bodyLines[signoffIdx].split(':').slice(1).join(':').trim();
        }
        if (!signoffValue || /not\s+required/i.test(signoffValue)) {
          findings.push({
            checkId: check.id,
            severity: 'block',
            message: 'High-risk tier requires a named human sign-off (name + date) in the spec.',
            source: 'validator'
          });
        }
      }
    }
  }

  return { verdict: verdictFrom(findings), tier, findings, gateSection };
}

import {
  Finding,
  GATE_CHECKS,
  GATE_HEADING,
  GateResult,
  RISK_TIERS,
  RiskTier,
  verdictFrom
} from './schema.js';

const PLACEHOLDER = /\b(TBD|TODO|FIXME|XXX)\b|\bfill\s+(this\s+)?in\b/i;
const UNRESOLVED = /NEEDS\s+HUMAN\s+INPUT/i;
/** A bold-labelled field line: `- **Retention**: 30 days` or `- **Retention:** 30 days`. */
const FIELD = /^(\s*)[-*]\s*\*\*([^*]+)\*\*(.*)$/;

function indentOf(line: string): number {
  return line.match(/^\s*/)![0].replace(/\t/g, '    ').length;
}

/** Text written inline after the field label (colon and hint stripped), or '' when none. */
function inlineValue(line: string): string {
  const m = line.match(FIELD);
  if (!m) return '';
  if (/:\s*$/.test(m[2])) return m[3].trim();
  if (/:\s*$/.test(m[3])) return '';
  // No trailing colon: the bold text itself is the content (`- **Currently implemented: none.**`).
  return m[3].replace(/^[^:]*:/, '').trim() || m[3].trim() || m[2].trim();
}

/** Lines indented deeper than the field at `idx`, blank lines included. */
function continuation(lines: string[], idx: number): string[] {
  const base = indentOf(lines[idx]);
  const out: string[] = [];
  for (let i = idx + 1; i < lines.length; i += 1) {
    if (lines[i].trim() && indentOf(lines[i]) <= base) break;
    out.push(lines[i]);
  }
  return out;
}

/** Indexes of field lines with no inline value and no answer on the indented lines below. */
function emptyFieldIndexes(lines: string[]): Set<number> {
  const empty = new Set<number>();
  for (let i = lines.length - 1; i >= 0; i -= 1) {
    if (!FIELD.test(lines[i]) || inlineValue(lines[i])) continue;
    // Inline text can be a hint only (`**Tier** (a / b):`); `inlineValue` already ignores it.
    const base = indentOf(lines[i]);
    let answered = false;
    for (let j = i + 1; j < lines.length; j += 1) {
      if (lines[j].trim() && indentOf(lines[j]) <= base) break;
      if (lines[j].trim() && !empty.has(j)) {
        answered = true;
        break;
      }
    }
    if (!answered) empty.add(i);
  }
  return empty;
}

/** Inline value plus indented continuation of the field at `idx`. */
function fieldText(lines: string[], idx: number): string {
  return [inlineValue(lines[idx]), ...continuation(lines, idx)].join('\n').trim();
}

interface Section {
  heading: string;
  body: string;
}

function stripComments(markdown: string): string {
  return markdown.replace(/<!--[\s\S]*?-->/g, '');
}

/** Extracts the Responsible AI Gate section: from its heading to the next heading of the same or higher level. */
export function extractGateSection(markdown: string): string | null {
  const lines = markdown.split(/\r?\n/);
  let start = -1;
  let level = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+(.*)$/);
    if (m && GATE_HEADING.test(m[2])) {
      start = i;
      level = m[1].length;
      break;
    }
  }
  if (start === -1) return null;
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+/);
    if (m && m[1].length <= level) {
      end = i;
      break;
    }
  }
  return lines.slice(start, end).join('\n');
}

/** Splits the gate section into subsections keyed by their headings (any level deeper than the gate heading). */
function splitSubsections(gateSection: string): Section[] {
  const lines = gateSection.split(/\r?\n/);
  const gateLevel = lines[0].match(/^(#{1,6})/)?.[1]?.length ?? 1;
  const sections: Section[] = [];
  let current: Section | null = null;
  for (const line of lines.slice(1)) {
    const m = line.match(/^(#{1,6})\s+(.*)$/);
    if (m && m[1].length > gateLevel) {
      if (current) sections.push(current);
      current = { heading: m[2].trim(), body: '' };
    } else if (current) {
      current.body += `${line}\n`;
    }
  }
  if (current) sections.push(current);
  return sections;
}

function extractTier(body: string): RiskTier | null {
  // When an explicit "Tier" field line exists, it is authoritative - a fallback body
  // search would pick up incidental mentions like "(tier below high)" in the sign-off.
  const lines = body.split(/\r?\n/);
  const fieldIdx = lines.findIndex(
    (l) => /\*\*tier:?\*\*/i.test(l) || /^\s*[-*]\s*tier\b/i.test(l)
  );
  // The answer may sit on indented lines below the label, so read the whole field.
  const haystacks = fieldIdx >= 0 ? [[lines[fieldIdx], ...continuation(lines, fieldIdx)].join('\n')] : [body];
  for (const text of haystacks) {
    // Skip the template's enum hint "(prohibited / high / limited / minimal)".
    const cleaned = text.replace(/\((?:[^)]*\/){2,}[^)]*\)/g, '');
    const found = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(cleaned));
    if (found.length === 1) return found[0];
    if (found.length > 1) {
      // Ambiguous mention; prefer the value after a colon on the field line.
      const afterColon = cleaned.split(':').slice(1).join(':');
      const inValue = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(afterColon));
      if (inValue.length === 1) return inValue[0];
    }
  }
  return null;
}

function answeredText(body: string): string {
  const lines = body.split(/\r?\n/);
  const empty = emptyFieldIndexes(lines);
  return lines
    .filter((_, i) => !empty.has(i))
    .join('\n')
    .trim();
}

export function validateSpec(markdown: string): GateResult {
  const findings: Finding[] = [];
  const clean = stripComments(markdown);
  const gateSection = extractGateSection(clean);

  if (!gateSection) {
    findings.push({
      checkId: 'structure',
      severity: 'block',
      message: 'No "## Responsible AI Gate" section found in the spec.',
      source: 'validator'
    });
    return { verdict: 'BLOCK', tier: null, findings, gateSection: null };
  }

  const subsections = splitSubsections(gateSection);
  let tier: RiskTier | null = null;

  for (const check of GATE_CHECKS) {
    const section = subsections.find((s) => check.headingPattern.test(s.heading));
    if (!section) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Missing gate subsection: "${check.title}".`,
        source: 'validator'
      });
