    }

    const body = section.body;
    const answered = answeredText(body);

    if (!answered) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" is present but empty.`,
        source: 'validator'
      });
      continue;
    }
    if (PLACEHOLDER.test(body)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" contains placeholder text (TBD/TODO). Answer it concretely.`,
        source: 'validator'
      });
    }
    if (UNRESOLVED.test(body)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" has unresolved "NEEDS HUMAN INPUT" items. Resolve them with a concrete answer.`,
        source: 'validator'
      });
    }
    const bodyLines = body.split(/\r?\n/);
    for (const i of emptyFieldIndexes(bodyLines)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Unanswered field in "${check.title}": ${bodyLines[i].trim()}`,
        source: 'validator'
      });
    }
    if (check.expectsNumbers && !/\d/.test(answered)) {
      findings.push({
        checkId: check.id,
        severity: 'warn',
        message: `"${check.title}" has no numeric threshold. A check that cannot fail is not a check.`,
        source: 'validator'
      });
    }

    if (check.id === 'risk-tier') {
      tier = extractTier(body);
      if (!tier) {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier must be one of: prohibited, high, limited, minimal.',
          source: 'validator'
        });
      } else if (tier === 'prohibited') {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier is "prohibited" - this feature must not be built.',
          source: 'validator'
        });
      } else if (tier === 'high') {
        const empty = emptyFieldIndexes(bodyLines);
        const labelled = bodyLines.findIndex(
          (l, i) => /^\s*[-*]\s*\*\*\s*sign[- ]?off/i.test(l) && !empty.has(i)
        );
        const signoffIdx =
          labelled >= 0
            ? labelled
            : bodyLines.findIndex((l, i) => /sign[- ]?off/i.test(l) && !empty.has(i));
        let signoffValue = '';
        if (signoffIdx >= 0) {
          signoffValue = FIELD.test(bodyLines[signoffIdx])
            ? fieldText(bodyLines, signoffIdx)
            : bodyLines[signoffIdx].split(':').slice(1).join(':').trim();
        }
        if (!signoffValue || /not\s+required/i.test(signoffValue)) {
          findings.push({
            checkId: check.id,
            severity: 'block',
            message: 'High-risk tier requires a named human sign-off (name + date) in the spec.',
            source: 'validator'
          });
        }
      }
    }
  }

  return { verdict: verdictFrom(findings), tier, findings, gateSection };
}

